td>28</td><td>N 22°06'56.97\" W</td><td>5.73</td><td>28</td><td>2,045,940.0963</td><td>357,704.8164</td></tr><tr><td>28</td><td>-</td><td>29</td><td>N 15°47'49.27\" W</td><td>5.73</td><td>29</td><td>2,045,945.6117</td><td>357,703.2560</td></tr><tr><td>29</td><td>-</td><td>30</td><td>N 09°28'41.56\" W</td><td>5.73</td><td>30</td><td>2,045,951.2653</td><td>357,702.3121</td></tr><tr><td>30</td><td>-</td><td>31</td><td>N 03°09'33.85\" W</td><td>5.73</td><td>31</td><td>2,045,956.9885</td><td>357,701.9962</td></tr><tr><td>31</td><td>-</td><td>32</td><td>N 00°00'00\" E</td><td>18.15</td><td>32</td><td>2,045,975.1347</td><td>357,701.9962</td></tr><tr><td>32</td><td>-</td><td>33</td><td>N 00°00'00\" E</td><td>136.60</td><td>33</td><td>2,046,111.7329</td><td>357,701.9962</td></tr><tr><td>33</td><td>-</td><td>1</td><td>N 86°20'42.56\" W</td><td>143.51</td><td>1</td><td>2,046,120.8810</td><td>357,558.7790</td></tr><tr><td colspan=\"8\">SUPERFICIE = 674,649.83 m2</td></tr></tbody></table>\n<p>CUADRO DE CONSTRUCCION SECCION II</p>\n<table><thead><tr><th colspan=\"8\">SECCION II</th></tr><tr><th rowspan=\"3\" colspan=\"3\">Est-PV</th><th rowspan=\"3\">Rumbo</th><th rowspan=\"3\">Distancia (en metros)</th><th>Vértice</th><th colspan=\"2\">Coordenadas UTM</th></tr><tr><th>Número</th><th>Y</th><th>X</th></tr></thead><tbody><tr><td>1</td><td>2'045,726.653</td><td>357,450.8390</td></tr><tr><td>1</td><td>-</td><td>2</td><td>S 86°28'27.00\" E</td><td>100.12</td><td>2</td><td>2'045,720.496</td><td>357,550.7680</td></tr><tr><td>2</td><td>-</td><td>3</td><td>S 07°39'06.00\" W</td><td>869.27</td><td>3</td><td>2'044,858.967</td><td>357,435.0230</td></tr><tr><td>3</td><td>-</td><td>4</td><td>S 76°15'31.00\" W</td><td>149.16</td><td>4</td><td>2'044,823.535</td><td>357,290.1310</td></tr><tr><td>4</td><td>-</td><td>5</td><td>N 02°11'15.00\" E</td><td>392.99</td><td>5</td><td>2'045,216.236</td><td>357,305.1320</td></tr><tr><td>5</td><td>-</td><td>1</td><td>N 15°55'56.00\" E</td><td>530.81</td><td>1</td><td>2'045,726.653</td><td>357,450.8390</td></tr><tr><td colspan=\"8\">SUPERFICIE = 130,802.47 m2</td></tr></tbody></table>\n<p>CUADRO DE CONTRUCCION SECCION III</p>\n<table><thead><tr><th colspan=\"8\">SECCION III</th></tr><tr><th rowspan=\"3\" colspan=\"3\">Est-PV</th><th rowspan=\"3\">Rumbo</th><th rowspan=\"3\">Distancia (en metros)</th><th>Vértice</th><th colspan=\"2\">Coordenadas UTM</th></tr><tr><th>Número</th><th>Y</th><th>X</th></tr></thead><tbody><tr><td>1</td><td>2,046,339.6104</td><td>356,953.0508</td></tr><tr><td>1</td><td>-</td><td>2</td><td>S 00°00'00\" E</td><td>185.03</td><td>2</td><td>2,046,154.5772</td><td>356,953.0508</td></tr><tr><td>2</td><td>-</td><td>3</td><td>S 87°21'36.75\" E</td><td>603.35</td><td>3</td><td>2,046,126.7890</td><td>357,555.7580</td></tr><tr><td>3</td><td>-</td><td>4</td><td>S 86°59'20.74\" E</td><td>170.61</td><td>4</td><td>2,046,117.8276</td><td>357,726.1319</td></tr><tr><td>4</td><td>-</td><td>5</td><td>N 00°00'00\" E</td><td>199.91</td><td>5</td><td>2,046,317.7333</td><td>357,726.1319</td></tr><tr><td>5</td><td>-</td><td>6</td><td>N 00°30'03.01\" E</td><td>30.39</td><td>6</td><td>2,046,348.1237</td><td>357,726.3975</td></tr><tr><td>6</td><td>-</td><td>7</td><td>N 89°28'34.62\" W</td><td>79.11</td><td>7</td><td>2,046,348.8467</td><td>357,647.2953</td></tr><tr><td>7</td><td>-</td><td>8</td><td>S 00°00'00\" E</td><td>173.99</td><td>8</td><td>2,046,174.8571</td><td>357,647.2953</td></tr><tr><td>8</td><td>-</td><td>9</td><td>N 89°59'50.53\" W</td><td>514.75</td><td>9</td><td>2,046,174.8808</td><td>357,132.5499</td></tr><tr><td>9</td><td>-</td><td>10</td><td>N 00°00'26.30\" E</td><td>161.78</td><td>10</td><td>2,046,336.6578</td><td>357,132.5705</td></tr><tr><td>10</td><td>-</td><td>1</td><td>N 89°03'27.80\" W</td><td>179.54</td><td>1</td><td>2,046,339.6104</td><td>356,953.0508</td></tr><tr><td colspan=\"8\">SUPERFICIE = 72,558.116 m2</td></tr></tbody></table>\n<p>RESUMEN SECCIONES</p>\n<table><thead><tr><th colspan=\"3\">SUPERFICIE TOTAL PODECOBI CHETUMAL I</th></tr><tr><th>SECCIONES</th><th>M2</th><th>HAS</th></tr></thead><tbody><tr><td>SECCION I</td><td>674,649.83</td><td>67.464983</td></tr><tr><td>SECCION II</td><td>130,802.47</td><td>13.080247</td></tr><tr><td>SECCION III</td><td>72,558.12</td><td>7.2558116</td></tr><tr><td>TOTAL</td><td>878,010.4160</td><td>87.8010</td></tr></tbody></table>\n<p>Figura 1. Mapa de ubicación del Polo de Desarrollo para el Bienestar Chetumal.</p>\n<p><a href=\"https://dof.gob.mx/abrirPDF.php?anio=2025&amp;archivo=01072025-MAT.pdf&amp;repo=#page=45\">Croquis de ubicación en el PDF oficial · página 45</a></p>\n<p>Elaboración propia, Dirección General de Innovación-Secretaría de Economía, 2025</p>","tipo_articulo":"ordinario","orden":3,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"990aed69-3f95-5bce-b208-d16b0ce5404b","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero","contenido":"<p>ARTÍCULO TERCERO. La superficie a que se refiere el artículo anterior cumple los criterios de selección establecidos en el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, publicado en el Diario Oficial de la Federación el 22 de mayo de 2025, como a continuación se señalan:</p>","tipo_articulo":"ordinario","orden":4,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"97b7d591-562a-5f8c-a163-fee283dfef91","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · I. Criterio de Macro Localización","contenido":"<p>I. Criterio de Macro Localización:</p>\n<p>La superficie del PODECOBI CHETUMAL, se ubica en el extremo sur de Quintana Roo, en la frontera con Belice, lo que le otorga una posición geopolítica clave para el comercio internacional y la cooperación transfronteriza. Los municipios aledaños son: al norte limita con el municipio de Bacalar del mismo estado; al oeste con el municipio de Calakmul del estado de Campeche, al sur con Belice, en particular con el Distrito de Corozal y el Distrito de Orange Walk.</p>","tipo_articulo":"ordinario","orden":5,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"edb90d94-d6fe-5427-b38b-862750df6315","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · II. Criterio de Comunicación y Conectividad","contenido":"<p>II. Criterio de Comunicación y Conectividad:</p>\n<p>El PODECOBI CHETUMAL dispone de infraestructura de conectividad terrestre, mediante la carretera federal 186 Escárcega - Chetumal que vincula el polo con el centro y norte del estado, así como con la frontera con Belice. El Aeropuerto Internacional de Chetumal y la estación del Tren Maya, Chetumal Aeropuerto se ubican a 3.5 km. El puerto marítimo Chetumal se ubica a 2 km del sitio, lo que posiciona al polo como un nodo regional. De igual manera, la frontera con Belice se ubica a 7.4 km.</p>","tipo_articulo":"ordinario","orden":6,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"45c144cd-85db-5bf3-a13b-9b242c24e3ee","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · III. Criterio Poblacional","contenido":"<p>III. Criterio Poblacional:</p>\n<p>Conforme al Censo de Población y Vivienda 2020(2), la población total de Othón P. Blanco y los municipios mencionados en el párrafo anterior es mayor a 50,000 habitantes.</p>\n<table><thead><tr><th>Municipio Sede y Municipios Aledaños</th><th>Población Censo 2020</th><th>Población total</th></tr></thead><tbody><tr><td>Othón P. Blanco</td><td>233,648</td><td rowspan=\"2\">275,402</td></tr><tr><td>Bacalar</td><td>41,754</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":7,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"f2e8f1d1-b3bf-55eb-9eb7-a767da7c224f","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · IV. Criterio de Factibilidad Social","contenido":"<p>IV. Criterio de Factibilidad Social:</p>\n<p>El Instituto Nacional de los de los Pueblos Indígenas, a través del oficio núm. CGDI/2025/OF/582 de fecha 06 de junio de 2025, comunicó que \"(...) Con relación al proyecto en cuestión, se informa que día 01 de febrero de 2024, esta Coordinación General de Derechos Indígenas recibió el oficio No. INMAYA/DG/0068/II2024 de la misma fecha, por parte del Instituto para el Desarrollo del Pueblo Maya y las Comunidades Indígenas del estado de Quintana Roo (INMAYA), por el que se solicitaba emitir dictamen sobre la procedencia de la consulta indígena respecto de la integración de una superficie territorial de 986,491.02 metros cuadrados pertenecientes al municipio de Othon P. Blanco, Quintana Roo, en el marco del Acuerdo por el que se emite la Declaratoria de Polo de Desarrollo Industrial para el Bienestar Chetumal I, mismo que coincide con la superficie requerida en su solicitud para el Proyecto de Creación de un Polo de Desarrollo Económico del Bienestar (PODECOBI) Chetumal I en el estado de Quintana Roo.</p>\n<p>En respuesta se emitió el Dictamen sobre el ejercicio del derecho de Consulta Previa, Libre e Informada a Pueblos y Comunidades Indígenas mediante oficio número CGDI/2024/OF/0532 fechado el 05 de febrero de 2024 y enviado mediante correo electrónico oficial en la misma fecha, por el que se determinó que no era procedente llevar a cabo el proceso de consulta indígena (...)\".</p>","tipo_articulo":"ordinario","orden":8,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"44dfc466-3e24-5247-a61c-3da3306bdf10","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · V. Criterio Educativo","contenido":"<p>V. Criterio Educativo:</p>\n<p>En el PODECOBI CHETUMAL, y el municipio aledaño a este, Bacalar se localizan las siguientes instituciones de educación media superior y superior:</p>\n<table><thead><tr><th>INSTITUCIONES DE EDUCACION SUPERIOR</th></tr></thead><tbody><tr><td>Bacalar</td></tr><tr><td>Universidad para la Cooperación Internacional</td></tr><tr><td>Centro Regional de Educación Normal Javier Rojo Gómez</td></tr><tr><td>Universidad Politécnica de Bacalar</td></tr></tbody></table>\n<table><thead><tr><th>Othón P. Blanco</th></tr></thead><tbody><tr><td>Universidad Interamericana para el Desarrollo Campus Chetumal</td></tr><tr><td>Centro de Actualización del Magisterio</td></tr><tr><td>Instituto Universitario Carl Rogers</td></tr><tr><td>Universidad Modelo</td></tr><tr><td>Instituto Mexicano de Estudios Pedagógicos</td></tr><tr><td>Instituto Interamericano de Ciencias de la Salud Sede Chetumal</td></tr><tr><td>Instituto de Investigación y Desarrollo Educativo de Quintana Roo</td></tr><tr><td>Universidad Vizcaya de las Américas</td></tr><tr><td>Escuela Judicial del Poder Judicial del Estado de Quintana Roo</td></tr><tr><td>Universidad Aztlán Campus Chetumal</td></tr><tr><td>Instituto de Estudios Superiores Lamat</td></tr><tr><td>Instituto de Estudios Superiores Wozniak</td></tr><tr><td>Instituto de Estudios Superiores Viktor Frankl</td></tr><tr><td>Instituto de Estudios Superiores para la Competitividad y el Desarrollo de América</td></tr><tr><td>Instituto Universitario del Caribe</td></tr><tr><td>Instituto de Educación Superior on line Cetec</td></tr><tr><td>Escuela de Terapia Física Dr. Alfonso Tohen Zamudio</td></tr><tr><td>Instituto de Formación Especializada en Derechos Humanos</td></tr><tr><td>Universidad de Ciencias y Disciplinas de la Seguridad de Quintana Roo</td></tr><tr><td>\"Ikal-Om\" Instituto Holístico y Ciencias Alternativas</td></tr><tr><td>Centro Universitario City College</td></tr><tr><td>Instituto Tecnológico de Chetumal</td></tr><tr><td>Universidad Tecnológica de Chetumal</td></tr><tr><td>Universidad de Alto Rendimiento y Especialización</td></tr><tr><td>Instituto Tecnológico de la Zona Maya</td></tr><tr><td>Instituto Universitario Wozniak</td></tr><tr><td>Centro Universitario de Desarrollo Vanguardista</td></tr><tr><td>Centro Educativo y Desarrollo Profesional Pittman</td></tr><tr><td>Centro de Enseñanza Superior de la Escuela Modelo</td></tr><tr><td>Instituto Tecnológico de la Construcción</td></tr><tr><td>Universidad Autónoma del Estado de Quintana Roo Campus Chetumal Bahía</td></tr><tr><td>Universidad Autónoma del Estado de Quintana Roo Campus Chetumal Salud</td></tr><tr><td>Universidad Pedagógica Nacional Unidad 231 Chetumal</td></tr><tr><td>Unidad Regional de El Colegio De La Frontera Sur</td></tr></tbody></table>\n<table><thead><tr><th>INSTITUCIONES DE EDUCACION MEDIA SUPERIOR</th></tr></thead><tbody><tr><td>Bacalar</td></tr><tr><td>Plantel Maya Balam</td></tr><tr><td>Centro De Estudios de Bachillerato 5/9 Justo Sierra Méndez</td></tr><tr><td>Telebachillerato Comunitario</td></tr><tr><td>Telebachillerato Comunitario</td></tr><tr><td>Telebachillerato Comunitario Buenavista</td></tr><tr><td>Telebachillerato Comunitario Nuevo Jerusalén</td></tr><tr><td>Telebachillerato Comunitario Margarita Maza De Juárez</td></tr><tr><td>Telebachillerato Comunitario La Pantera</td></tr><tr><td>Telebachillerato Comunitario El Cedralito</td></tr><tr><td>Telebachillerato Comunitario Huatusco</td></tr><tr><td>Telebachillerato Comunitario Manuel Ávila Camacho</td></tr><tr><td>Telebachillerato Comunitario San Román</td></tr><tr><td>Bacalar</td></tr><tr><td>Othón P. Blanco</td></tr><tr><td>Centro De Bachillerato Tecnológico Agropecuario Núm. 11</td></tr><tr><td>Preparatoria Abierta Quintana Roo</td></tr><tr><td>Escuela De Danza Clásica Patty</td></tr><tr><td>Colegio De Estudios Científicos Y Tecnológicos Unidad Chetumal</td></tr><tr><td>Telebachillerato Comunitario</td></tr><tr><td>Telebachillerato Comunitario</td></tr><tr><td>Telebachillerato Comunitario</td></tr><tr><td>Colegio Latino</td></tr><tr><td>Centro De Estudios Tecnológicos Del Mar Núm. 10</td></tr><tr><td>Instituto Lamat</td></tr><tr><td>Preparatoria Escuela Modelo</td></tr><tr><td>Instituto Smic</td></tr><tr><td>Centro de Bachillerato Tecnológico Industrial y de Servicios Núm. 214</td></tr><tr><td>Preparatoria on line Cetec</td></tr><tr><td>Centro De Bachillerato Tecnológico Industrial Y De Servicios Núm. 214</td></tr><tr><td>Instituto Vanguardia Educativa</td></tr><tr><td>Plantel Conalep 007. Lic. Jesús Martínez Ross- Chetumal</td></tr><tr><td>Telebachillerato Comunitario Allende</td></tr><tr><td>Telebachillerato Comunitario Huay-Pix</td></tr><tr><td>Telebachillerato Comunitario Juan Sarabia</td></tr><tr><td>Telebachillerato Comunitario Morocoy</td></tr><tr><td>Centro De Bachillerato Tecnológico Industrial Y De Servicios Núm. 253</td></tr><tr><td>Telebachillerato Comunitario Tres Garantías</td></tr><tr><td>Centro Escolar Escocia</td></tr><tr><td>Centro de Bachillerato Tecnológico Industrial y de Servicios Núm. 253</td></tr><tr><td>Telebachillerato Comunitario Nuevo Becar</td></tr><tr><td>Telebachillerato Comunitario Felipe Angeles</td></tr><tr><td>Instituto Wozniak</td></tr><tr><td>Centro De Atención Para Estudiantes Con Discapacidad</td></tr><tr><td>Telebachillerato Comunitario Sergio Butrón Casas</td></tr><tr><td>Telebachillerato Comunitario La Unión</td></tr><tr><td>Telebachillerato Comunitario José Narciso Rovirosa</td></tr><tr><td>Centro de Atención para Estudiantes con Discapacidad</td></tr><tr><td>Telebachillerato Comunitario Xcalak</td></tr><tr><td>Instituto de la Cultura y las Artes de Quintana Roo</td></tr><tr><td>Bachillerato del Instituto de Estudios Superiores para la Competitividad y el Desarrollo de América</td></tr><tr><td>Instituto de Alto Rendimiento Educativo</td></tr><tr><td>Instituto Tadheuss</td></tr><tr><td>Colegio Imee Campestre</td></tr><tr><td>Telebachillerato Comunitario Cacao</td></tr><tr><td>Telebachillerato Comunitario Francisco Villa</td></tr><tr><td>Universidad Anáhuac Bachillerato Cumbres de Quintana Roo</td></tr><tr><td>Telebachillerato Comunitario Jesús González Ortega</td></tr><tr><td>Telebachillerato Comunitario Ramonal</td></tr><tr><td>Centro de Servicios Académicos Integrales Chetumal</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":9,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"08559940-fa8a-52d3-be25-c8dd9c9a5388","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · VI. Criterio Territorial","contenido":"<p>VI. Criterio Territorial:</p>\n<p>El PODECOBI CHETUMAL representa una estrategia para equilibrar el desarrollo regional de Quintana Roo, históricamente concentrado en la franja norte turística. Este polo posee una estructura administrativa consolidada y una posición geopolítica privilegiada al estar ubicado en la frontera con Belice y tener acceso directo al Mar Caribe. Esta condición lo convierte en un nodo potencial para el comercio transfronterizo, el turismo regional, y la logística internacional.</p>\n<p>Para el desarrollo de actividades productivas en el PODECOBI CHETUMAL son vocaciones productivas, prioritarias y potenciales las siguientes:</p>\n<p>· Energía eléctrica;</p>\n<p>· Industria textil;</p>\n<p>· Metalurgia;</p>\n<p>· Maquinaria y equipo;</p>\n<p>· Agroindustria;</p>\n<p>· Tecnologías de la información y Comunicación;</p>\n<p>· Actividades industriales y comercio internacional;</p>\n<p>· Almacenamiento y distribución de mercancías.</p>","tipo_articulo":"ordinario","orden":10,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"54b20f69-5924-541a-835c-aad71b3958af","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · VII. Criterio de Factibilidad Industrial","contenido":"<p>VII. Criterio de Factibilidad Industrial:</p>\n<p>De acuerdo con el número de oficio DGDUMAE/110/2025 expedido por Ayuntamiento de Othón P. Blanco el inmueble destinado al PODECOBI CHETUMAL se señala que el uso de suelo de \"Parque Industrial con Recinto Fiscalizado (PIRFE) - Polígono de actuación sujeto a programa parcial de desarrollo urbano\".</p>","tipo_articulo":"ordinario","orden":11,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"48ffac18-93dc-590d-9d5f-9772b45abe19","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · VIII. Criterio de Sostenibilidad","contenido":"<p>VIII. Criterio de Sostenibilidad:</p>\n<p>Conforme al dictamen individual de la Secretaría de Medio Ambiente y Recursos Naturales, de fecha 3 de junio, con número de oficio SDSEC/800/79/2025 el \"PODECOBI CHETUMAL, es viable en materia ambiental, sujeto al cumplimiento de los requisitos normativos aplicables y a la integración de medidas específicas para protección ecológica y gestión hídrica\". Asimismo, \"no se localiza dentro de Áreas Naturales Protegidas ni de tierras de pueblos indígenas\".</p>","tipo_articulo":"ordinario","orden":12,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"af313f3b-9a57-567b-a6f7-96bda3535483","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · IX. Criterio de Servicios e Infraestructura","contenido":"<p>IX. Criterio de Servicios e Infraestructura:</p>\n<p>El polígono cuenta con los servicios e infraestructura básicos para el desarrollo de las actividades productivas. Dispone de vialidades, energía eléctrica, agua potable y conectividad, lo que garantiza condiciones adecuadas para la operación de empresas e industrias, y contribuye al impulso del desarrollo regional y la atracción de inversiones.</p>","tipo_articulo":"ordinario","orden":13,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"65eb8d31-7586-5ff5-b9cb-45424ba71d7e","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo tercero · X. Criterio de Propiedad","contenido":"<p>X. Criterio de Propiedad:</p>\n<p>De conformidad con la información proporcionada por la entidad federativa y la documentación que fue puesta a disposición del Comité Intersecretarial de Promoción, se desprende que los predios que conforman el área destinada al PODECOBI CHETUMAL son de propiedad pública estatal.</p>","tipo_articulo":"ordinario","orden":14,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"9edb10e1-7b29-5f2c-8afa-3488d9f619a3","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Artículo cuarto","contenido":"<p>ARTÍCULO CUARTO. El estado de Quintana Roo y la Secretaría de Economía deberán suscribir el convenio de coordinación a que se refiere el artículo Décimo, párrafo tercero del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.</p>","tipo_articulo":"ordinario","orden":15,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"d2b7c0f3-3fcd-5fff-a43e-c676e1318247","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Transitorio único","contenido":"<p>TRANSITORIO</p>\n<p>ÚNICO. La presente Declaratoria entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.</p>","tipo_articulo":"transitorio","orden":16,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"e1d5a16a-5d1b-5ebf-9a4a-3d2bfbb14eee","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Firma del acuerdo","contenido":"<p>Ciudad de México, a diecinueve de junio de 2025.- El Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.</p>","tipo_articulo":"complementario","orden":17,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"a4f9fbc7-30f6-5fa6-886d-181c5c0249a8","ley_id":"3a3de35c-c6ea-56a3-a4bc-2a5c13313704","identificador":"Notas al pie","contenido":"<p>1 https://www.gob.mx/cms/uploads/attachment/file/981072/PND_2025-2030_v250226_14.pdf</p>\n<p>2 Inegi (2020). Censo de Población y Vivienda 2020. Instituto Nacional de Estadística y Geografía (INEGI). https://www.inegi.org.mx/</p>","tipo_articulo":"nota","orden":18,"titulo_nombre":"Chetumal","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
END
$carga$;
